import React, { useState, useContext } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import backgroundImage from "../Img/order5.jpg";
import { OrderContext } from "../context/OrderContext"; // Import OrderContext

const AddOrder = () => {
  const { setOrdersChanged } = useContext(OrderContext); // Use Context to trigger updates
  const navigate = useNavigate();

  // Order Data State
  const [orderData, setOrderData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phoneNumber: "",
    address: "",
    city: "",
    orderId: "",
    specialInstructions: "",
    pickupTime: "",
    orderStatus: "",
  });

  // Handle Input Change
  const handleChange = (e) => {
    setOrderData({ ...orderData, [e.target.name]: e.target.value });
  };

  // Form Submit Handler
  const sendData = async (e) => {
    e.preventDefault();

    // Validation: Ensure required fields are filled
    if (!orderData.firstName || !orderData.lastName || !orderData.email || !orderData.phoneNumber) {
      alert("Please fill in all required fields!");
      return;
    }

    try {
      await axios.post("http://localhost:5000/orders/", orderData);
      alert("Order Added Successfully!");

      // Trigger Order Update for AllOrders page
      setOrdersChanged((prev) => !prev);

      // Reset Form
      setOrderData({
        firstName: "",
        lastName: "",
        email: "",
        phoneNumber: "",
        address: "",
        city: "",
        orderId: "",
        specialInstructions: "",
        pickupTime: "",
        orderStatus: "",
      });

      // Navigate to All Orders Page
      navigate("/all-orders");
    } catch (error) {
      alert("Error adding order: " + error.response?.data?.message || error.message);
    }
  };

  return (
    <div
      style={{
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        minHeight: "100vh",
        backgroundColor: "#f0f0f0",
        backgroundImage: `url(${backgroundImage})`,
        backgroundSize: "cover",
        backgroundRepeat: "no-repeat",
        backgroundBlendMode: "multiply",
      }}
    >
      <div
        style={{
          backgroundColor: "rgba(255, 255, 255, 0.8)",
          padding: "20px",
          borderRadius: "10px",
          boxShadow: "0px 4px 10px rgba(0, 0, 0, 0.1)",
          width: "100%",
          maxWidth: "600px",
          boxSizing: "border-box",
        }}
      >
        <h1 style={{ color: "#8B0000", fontWeight: "bold", textAlign: "center", marginBottom: "20px" }}>
          Add Order
        </h1>
        <form onSubmit={sendData} style={{ width: "100%" }}>
          {["firstName", "lastName", "email", "phoneNumber", "address", "city", "orderId", "specialInstructions", "pickupTime", "orderStatus"].map(
            (field) => (
              <div key={field} style={{ marginBottom: "15px" }}>
                <label htmlFor={field} style={{ display: "block", fontWeight: "bold" }}>
                  {field.replace(/([A-Z])/g, " $1").trim()}
                </label>
                <input
                  type={field === "email" ? "email" : "text"}
                  id={field}
                  name={field}
                  style={{
                    width: "100%",
                    padding: "10px",
                    border: "1px solid #ccc",
                    borderRadius: "5px",
                    boxSizing: "border-box",
                  }}
                  placeholder={`Enter ${field}`}
                  value={orderData[field]}
                  onChange={handleChange}
                  required={["firstName", "lastName", "email", "phoneNumber"].includes(field)}
                />
              </div>
            )
          )}
          <button
            type="submit"
            style={{
              backgroundColor: "#b30000",
              color: "white",
              padding: "10px 20px",
              border: "none",
              borderRadius: "5px",
              cursor: "pointer",
              fontSize: "16px",
              marginBottom: "10px",
            }}
          >
            Submit
          </button>
        </form>
        <div style={{ display: "flex", justifyContent: "center" }}>
          <button
            onClick={() => navigate("/")}
            style={{
              backgroundColor: "#b30000",
              color: "white",
              padding: "10px 20px",
              border: "none",
              borderRadius: "5px",
              cursor: "pointer",
              fontSize: "16px",
              width: "30%",
              marginTop: "10px",
            }}
          >
            Back to Home
          </button>
        </div>
      </div>
    </div>
  );
};

export default AddOrder;
